function write( relative: string, content = '' ): void {
	const file = path.join( root, relative );
	mkdirSync( path.dirname( file ), { recursive: true } );
	writeFileSync( file, content );
}

function mainFile( version: string ): string {
	return `<?php\n/**\n * Plugin Name: WP Simple Pay Pro\n * Version: ${ version }\n */\n\nif ( ! defined( 'SIMPLE_PAY_VERSION' ) ) {\n\tdefine( 'SIMPLE_PAY_VERSION', '${ version }' );\n}\n`;
}

