describe( 'stageStates', () => {
	const release = parseVersion( '4.17.5' )!;
	const hotfix = parseVersion( '4.17.4.1' )!;

	it( 'blocks every stage after Analyze until the analysis exists', () => {
		const result = states( release );

		expect( result.analyze ).toMatchObject( { status: 'ready', tracked: true, blockedReason: null } );

		for ( const id of [ 'prep', 'docs', 'marketing' ] ) {
			expect( result[ id ].status ).toBe( 'blocked' );
			expect( result[ id ].blockedReason ).toContain( 'docs/releases/4.17.5/release.md' );
		}
	} );

	it( 'marks Analyze done and unblocks the rest once release.md exists', () => {
		write( 'docs/releases/4.17.5/release.md', '# Release' );
		const result = states( release );

		expect( result.analyze.status ).toBe( 'done' );
		expect( result.prep.status ).toBe( 'ready' );
		expect( result.docs ).toMatchObject( { status: 'ready', tracked: false } );
		expect( result.marketing.status ).toBe( 'ready' );
	} );

	it( 'uses the hotfix analysis file, not release.md, for a 4-part version', () => {
		write( 'docs/releases/4.17.4/release.md' );
		expect( states( hotfix ).analyze.status ).toBe( 'ready' );

		write( 'docs/releases/4.17.4/4.17.4.1.md' );
		expect( states( hotfix ).analyze.status ).toBe( 'done' );
	} );

	it( 'marks Prep done only when both version strings match and the site changes report exists', () => {
		write( 'docs/releases/4.17.5/release.md' );
		write( 'simple-pay.php', mainFile( '4.17.5' ) );
		expect( states( release ).prep.status ).toBe( 'ready' );

		write( 'docs/releases/4.17.5/marketing-site-changes.md' );
		expect( states( release ).prep.status ).toBe( 'done' );
	} );

	it( 'does not mark Prep done when only the header was bumped', () => {
		write( 'docs/releases/4.17.5/release.md' );
		write( 'docs/releases/4.17.5/marketing-site-changes.md' );
		write( 'simple-pay.php', mainFile( '4.17.4' ).replace( 'Version: 4.17.4', 'Version: 4.17.5' ) );

		expect( states( release ).prep.status ).toBe( 'ready' );
	} );

	it( 'does not treat a longer version as a match (4.17.5 vs 4.17.5.1)', () => {
		write( 'docs/releases/4.17.5/release.md' );
		write( 'docs/releases/4.17.5/marketing-site-changes.md' );
		write( 'simple-pay.php', mainFile( '4.17.5.1' ) );

		expect( states( release ).prep.status ).toBe( 'ready' );
	} );

	it( 'reports Prep as not done when simple-pay.php is missing', () => {
		write( 'docs/releases/4.17.5/release.md' );
		write( 'docs/releases/4.17.5/marketing-site-changes.md' );

		expect( states( release ).prep.status ).toBe( 'ready' );
	} );

	it( 'uses the suffixed site changes report for a hotfix', () => {
		write( 'docs/releases/4.17.4/4.17.4.1.md' );
		write( 'simple-pay.php', mainFile( '4.17.4.1' ) );
		write( 'docs/releases/4.17.4/marketing-site-changes.md' );
		expect( states( hotfix ).prep.status ).toBe( 'ready' );

		write( 'docs/releases/4.17.4/marketing-site-changes-4.17.4.1.md' );
		expect( states( hotfix ).prep.status ).toBe( 'done' );
	} );

	it( 'lists the Marketing files that are still missing', () => {
		write( 'docs/releases/4.17.5/release.md' );
		marketingAssets( release ).filter( ( file ) => ! file.endsWith( '.jpg' ) ).forEach( ( file ) => write( file ) );

		expect( states( release ).marketing.missing ).toEqual( [ 'blog-4.17.5-featured-image.jpg' ] );
		expect( states( release ).analyze.missing ).toEqual( [] );
	} );

		it( 'marks Marketing done only when every asset exists', () => {
		write( 'docs/releases/4.17.5/release.md' );
		const assets = marketingAssets( release );

		assets.slice( 0, -1 ).forEach( ( file ) => write( file ) );
		expect( states( release ).marketing.status ).toBe( 'ready' );

		write( assets[ assets.length - 1 ] );
		expect( states( release ).marketing.status ).toBe( 'done' );
	} );

	it( 'shows a done stage as done even if its prerequisite later disappeared', () => {
		marketingAssets( release ).forEach( ( file ) => write( file ) );

		expect( states( release ).marketing ).toMatchObject( { status: 'done', blockedReason: null } );
	} );
} );

