describe( 'phase 3 stages', () => {
	const release = parseVersion( '4.17.5' )!;
	let lite: string;

	beforeEach( () => {
		lite = path.join( root, 'lite' );
	} );

	function stateOf( id: string ) {
		return stageStates( { root, version: release, litePath: lite } ).find( ( stage ) => stage.id === id )!;
	}

	function gitTag( repo: string, tag: string, packed = false ): void {
		if ( packed ) {
			write( path.relative( root, path.join( repo, '.git/packed-refs' ) ), `# pack-refs with: peeled\nabc123 refs/tags/${ tag }\n` );
		} else {
			write( path.relative( root, path.join( repo, '.git/refs/tags', tag ) ), 'abc123\n' );
		}
	}

	it( 'groups stages in pipeline order', () => {
		expect( STAGES.map( ( stage ) => stage.group ) ).toEqual( [ 'qa', 'qa', 'prepare', 'prepare', 'prepare', 'prepare', 'publish', 'publish', 'publish', 'publish', 'ship', 'ship', 'ship', 'ship' ] );
	} );

	it( 'marks only the publishing stages irreversible, and only the browser stages as using Chrome', () => {
		expect( STAGES.filter( ( stage ) => stage.irreversible ).map( ( stage ) => stage.id ) ).toEqual( [ 'create-release', 'lite-publish', 'lite-wporg' ] );
		// Marketing's featured image is generated in Chatty through Chrome.
		expect( STAGES.filter( ( stage ) => stage.browser ).map( ( stage ) => stage.id ) ).toEqual( [ 'marketing', 'blog-draft', 'email-draft', 'notifications-draft', 'notifications' ] );
	} );

	it( 'detects the milestone review and the build report', () => {
		expect( stateOf( 'review-milestone' ).status ).toBe( 'ready' );
		write( 'docs/releases/4.17.5/reviews/README.md' );
		expect( stateOf( 'review-milestone' ).status ).toBe( 'done' );

		expect( stateOf( 'compare-builds' ).status ).toBe( 'ready' );
		write( 'build-audit/reports/4.17.5-build-diff.md' );
		expect( stateOf( 'compare-builds' ).status ).toBe( 'done' );
	} );

	it( 'blocks the blog draft until the post and a featured image exist, in any supported format', () => {
		expect( stateOf( 'blog-draft' ).blockedReason ).toContain( 'blog.html' );

		write( 'docs/releases/4.17.5/blog.html' );
		expect( stateOf( 'blog-draft' ).blockedReason ).toContain( 'featured image' );

		write( 'docs/releases/4.17.5/blog-4.17.5-featured-image.webp' );
		expect( stateOf( 'blog-draft' ) ).toMatchObject( { status: 'ready', tracked: false } );
	} );

	it( 'marks the Pro release done once its tag exists, loose or packed', () => {
		mkdirSync( path.join( root, '.git' ), { recursive: true } );
		expect( stateOf( 'create-release' ).status ).toBe( 'ready' );

		gitTag( root, '4.17.5', true );
		expect( stateOf( 'create-release' ).status ).toBe( 'done' );
	} );

	it( 'does not confuse a similar tag with this one', () => {
		gitTag( root, '4.17.5.1' );
		gitTag( root, '14.17.5', true );

		expect( stateOf( 'create-release' ).status ).toBe( 'ready' );
	} );

	it( 'ignores a .git file (a worktree) instead of failing', () => {
		write( '.git', 'gitdir: /elsewhere' );

		expect( stateOf( 'create-release' ).status ).toBe( 'ready' );
	} );

	it( 'detects the Lite sync from Lite’s header version, and the Lite release from its tag', () => {
		expect( stateOf( 'lite-sync' ).status ).toBe( 'ready' );
		expect( stateOf( 'lite-publish' ) ).toMatchObject( { status: 'blocked', blockedReason: expect.stringContaining( 'Run Sync release to Lite repo first' ) } );

		write( 'lite/stripe-checkout.php', '<?php\n/**\n * Plugin Name: WP Simple Pay Lite\n * Version: 4.17.4\n */' );
		expect( stateOf( 'lite-sync' ).status ).toBe( 'ready' );
		expect( stateOf( 'lite-publish' ).status ).toBe( 'ready' );

		write( 'lite/stripe-checkout.php', '<?php\n/**\n * Plugin Name: WP Simple Pay Lite\n * Version: 4.17.5\n */' );
		expect( stateOf( 'lite-sync' ).status ).toBe( 'done' );

		gitTag( lite, '4.17.5' );
		expect( stateOf( 'lite-publish' ).status ).toBe( 'done' );
	} );

	it( 'blocks the wp.org release until Lite is tagged, and never counts a working copy that is not there', () => {
		expect( stateOf( 'lite-wporg' ) ).toMatchObject( { status: 'blocked', tracked: true, blockedReason: expect.stringContaining( 'Run Publish Lite release on GitHub first' ) } );

		gitTag( lite, '4.17.5' );
		expect( stateOf( 'lite-wporg' ).status ).toBe( 'ready' );

		// A folder with the header but no .svn is not a working copy.
		write( 'svn/trunk/stripe-checkout.php', ' * Version: 4.17.5\n' );
		expect( svnTrunkReleased( path.join( root, 'svn' ), '4.17.5' ) ).toBe( false );
	} );

	it( 'shows a Lite release published on GitHub as done, and asks before running it again', () => {
		const version = parseVersion( '4.17.5' )!;
		const release = { exists: true as const, tag: '4.17.5', url: 'https://github.com/x/releases/tag/4.17.5', publishedAt: '2026-10-14T14:15:46Z', isDraft: false, assets: [ 'stripe-4.17.5.zip' ] };
		const stateWith = ( liteRelease: Parameters<typeof stageStates>[ 0 ][ 'liteRelease' ], id: string ) =>
			stageStates( { root, version, litePath: lite, liteRelease } ).find( ( stage ) => stage.id === id )!;

		write( 'lite/stripe-checkout.php', ' * Version: 4.17.5\n' );

		// No local tag: the console used to call this ready.
		expect( stateWith( release, 'lite-publish' ) ).toMatchObject( {
			status: 'done',
			remote: {
				tone: 'success',
				text: expect.stringContaining( 'already released on GitHub on 2026-10-14, with stripe-4.17.5.zip' ),
				url: release.url,
				rerunWarning: expect.stringContaining( 'will not publish a second release' ),
			},
		} );
		expect( stateWith( { ...release, assets: [] }, 'lite-publish' ).remote ).toMatchObject( { tone: 'warning', text: expect.stringContaining( 'is not attached' ) } );

		// A draft is not public, so the stage is not done.
		expect( stateWith( { ...release, isDraft: true }, 'lite-publish' ) ).toMatchObject( { status: 'ready', remote: { tone: 'warning', rerunWarning: null } } );

		expect( stateWith( { exists: false, tag: '4.17.5' }, 'lite-publish' ) ).toMatchObject( { status: 'ready', remote: null } );
		expect( stateWith( null, 'lite-publish' ) ).toMatchObject( { status: 'ready', remote: null } );
	} );

	it( 'unlocks the wp.org release once the zip is on Lite’s GitHub release', () => {
		const version = parseVersion( '4.17.5' )!;
		const release = { exists: true as const, tag: '4.17.5', url: 'https://github.com/x/releases/tag/4.17.5', publishedAt: null, isDraft: false, assets: [ 'stripe-4.17.5.zip' ] };
		const wporg = ( liteRelease: Parameters<typeof stageStates>[ 0 ][ 'liteRelease' ] ) =>
			stageStates( { root, version, litePath: lite, svnPath: path.join( root, 'no-svn' ), liteRelease } ).find( ( stage ) => stage.id === 'lite-wporg' )!;

		// No local tag needed when GitHub has the zip.
		expect( wporg( release ) ).toMatchObject( { status: 'ready', blockedReason: null, remote: { tone: 'success', text: expect.stringContaining( 'stripe-4.17.5.zip' ) } } );

		expect( wporg( { ...release, assets: [ 'other.zip' ] } ) ).toMatchObject( { status: 'blocked', blockedReason: expect.stringContaining( 'has no stripe-4.17.5.zip attached' ), remote: null } );
		expect( wporg( { ...release, isDraft: true } ).blockedReason ).toContain( 'still a draft' );
		expect( wporg( { exists: false, tag: '4.17.5' } ).blockedReason ).toContain( 'GitHub has no Lite 4.17.5 release yet' );

		// GitHub could not be asked: the local tag stands in.
		expect( wporg( null ).blockedReason ).toContain( 'GitHub could not be checked' );
		gitTag( lite, '4.17.5' );
		expect( wporg( null ).status ).toBe( 'ready' );

		// A local tag does not override what GitHub says is missing.
		expect( wporg( { exists: false, tag: '4.17.5' } ).status ).toBe( 'blocked' );
	} );

	it.skipIf( ! hasSvn )( 'counts the wp.org release done only once trunk is committed at the version, not just staged', () => {
		const repo = path.join( root, 'svn-repo' );
		const wc = path.join( root, 'svn-wc' );
		const svn = ( ...args: string[] ) => execFileSync( 'svn', args, { cwd: root, stdio: 'pipe' } );

		execFileSync( 'svnadmin', [ 'create', repo ] );
		svn( 'checkout', '-q', `file://${ repo }`, wc );
		mkdirSync( path.join( wc, 'trunk' ) );
		writeFileSync( path.join( wc, 'trunk/stripe-checkout.php' ), '<?php\n/**\n * Version: 4.17.4\n */\n' );
		svn( 'add', '-q', path.join( wc, 'trunk' ) );
		svn( 'commit', '-q', '-m', 'Updating trunk to 4.17.4', wc );

		const status = () => stageStates( { root, version: release, litePath: lite, svnPath: wc } ).find( ( stage ) => stage.id === 'lite-wporg' )!.status;

		gitTag( lite, '4.17.5' );
		expect( status() ).toBe( 'ready' );

		// Phase 1 staged the new header but has not committed it.
		writeFileSync( path.join( wc, 'trunk/stripe-checkout.php' ), '<?php\n/**\n * Version: 4.17.5\n */\n' );
		expect( status() ).toBe( 'ready' );

		svn( 'commit', '-q', '-m', 'Updating trunk to 4.17.5', wc );
		expect( status() ).toBe( 'done' );
	} );

	it( 'drafts the email campaign once the newsletter exists, and cannot track it on disk', () => {
		expect( stateOf( 'email-draft' ) ).toMatchObject( { status: 'blocked', blockedReason: expect.stringContaining( 'newsletter.html' ), tracked: false } );

		write( 'docs/releases/4.17.5/newsletter.html', '<!-- Subject line (selected): x -->' );
		expect( stateOf( 'email-draft' ) ).toMatchObject( {
			status: 'ready',
			tracked: false,
			browser: true,
			irreversible: false,
			review: { type: 'file', path: 'docs/releases/4.17.5/newsletter.html' },
		} );
	} );

	it( 'drafts notifications once the copy exists, and reads the feeds to tell it is done', () => {
		const version = parseVersion( '4.17.5' )!;
		const note = ( id: number, type: string[] ) => ( { id, title: 't', content: '<strong>WP Simple Pay 4.17.5</strong>', type } );
		const draft = ( notificationFeeds: Parameters<typeof stageStates>[ 0 ][ 'notificationFeeds' ] ) =>
			stageStates( { root, version, litePath: lite, notificationFeeds } ).find( ( stage ) => stage.id === 'notifications-draft' )!;

		expect( draft( undefined ) ).toMatchObject( { status: 'blocked', blockedReason: expect.stringContaining( 'notification-pro.html' ), tracked: false } );
		write( 'docs/releases/4.17.5/notification-pro.html', 'Title: x' );
		expect( draft( undefined ).blockedReason ).toContain( 'notification-lite.html' );
		write( 'docs/releases/4.17.5/notification-lite.html', 'Title: x' );

		// Untracked without the feeds; tracked and not done when they have nothing.
		expect( draft( undefined ) ).toMatchObject( { status: 'ready', tracked: false, remote: null } );
		expect( draft( null ) ).toMatchObject( { status: 'ready', tracked: false } );
		expect( draft( { live: [], draft: [] } ) ).toMatchObject( { status: 'ready', tracked: true, remote: null } );

		// Only Pro drafted: not done, and says what is missing.
		expect( draft( { live: [], draft: [ note( 9, [ 'elite', 'plus' ] ) ] } ) ).toMatchObject( {
			status: 'ready',
			remote: { tone: 'warning', text: expect.stringContaining( 'Pro #9 (draft). One audience is missing.' ) },
		} );

		const both = draft( { live: [ note( 9, [ 'elite' ] ) ], draft: [ note( 9, [ 'elite' ] ), note( 10, [ 'lite' ] ) ] } );
		expect( both ).toMatchObject( {
			status: 'done',
			remote: {
				tone: 'success',
				text: 'On plugin.wpsimplepay.com: Pro #9 (published), Lite #10 (draft).',
				rerunWarning: expect.stringContaining( 'at least one is published' ),
			},
		} );
	} );

	it( 'passes the browser and irreversible flags through to the stage state', () => {
		expect( stateOf( 'create-release' ) ).toMatchObject( { irreversible: true, browser: false, review: null } );
		expect( stateOf( 'notifications' ) ).toMatchObject( { irreversible: false, browser: true, group: 'publish' } );
	} );
} );

