describe( 'localBuildChoices', () => {
	const release = parseVersion( '4.17.5' )!;
	const compare = findStage( 'compare-builds' )!;

	function record( id: string, overrides: Partial<BuildRecord> = {} ): BuildRecord {
		return {
			id,
			version: '4.17.5',
			lite: true,
			status: 'done',
			startedAt: Number( id.slice( -4 ) ),
			endedAt: Number( id.slice( -4 ) ) + 1,
			steps: [],
			artifacts: [
				{ name: 'wp-simple-pay-pro-4.17.5.zip', size: 10, kind: 'pro' },
				{ name: 'stripe-4.17.5.zip', size: 10, kind: 'lite' },
			],
			error: null,
			git: { branch: 'release/4.17.5', commit: 'abc1234', changes: 0 },
			...overrides,
		};
	}

	function source( id: string, overrides: Partial<BuildRecord> = {}, dir = path.join( root, '.builds', id ) ): LocalBuildSource {
		const build = record( id, overrides );

		for ( const artifact of build.artifacts ) {
			write( path.relative( root, path.join( dir, artifact.name ) ), 'zip' );
		}

		return { record: build, dir };
	}

	const choices = ( localBuilds: LocalBuildSource[], stage = compare ) =>
		localBuildChoices( stage, { root, version: release, litePath: path.join( root, 'lite' ), localBuilds } );

	it( 'builds the command for a Pro and Lite build, with the commit it came from', () => {
		const [ choice ] = choices( [ source( '20261013-120000-0001' ) ] );

		expect( choice ).toMatchObject( { id: '20261013-120000-0001', lite: true, commit: 'abc1234', changes: 0 } );
		expect( choice.prompt ).toBe(
			'/wpsp-compare-builds 4.17.5 --candidate .builds/20261013-120000-0001/wp-simple-pay-pro-4.17.5.zip --lite-candidate .builds/20261013-120000-0001/stripe-4.17.5.zip --candidate-commit abc1234'
		);
	} );

	it( 'marks a Pro-only build and one with uncommitted files', () => {
		const [ choice ] = choices( [
			source( '20261013-120000-0002', {
				lite: false,
				artifacts: [ { name: 'wp-simple-pay-pro-4.17.5.zip', size: 10, kind: 'pro' } ],
				git: { branch: 'release/4.17.5', commit: 'def5678', changes: 3 },
			} ),
		] );

		expect( choice.lite ).toBe( false );
		expect( choice.liteZip ).toBeNull();
		expect( choice.prompt ).toContain( '--pro-only' );
		expect( choice.prompt ).not.toContain( '--lite-candidate' );
		expect( choice.prompt ).toContain( '--candidate-commit def5678 --candidate-uncommitted 3' );
	} );

	it( 'leaves the commit out when the build recorded no git state', () => {
		const [ choice ] = choices( [ source( '20261013-120000-0003', { git: null } ) ] );

		expect( choice.prompt ).not.toContain( '--candidate-commit' );
		expect( choice.commit ).toBeNull();
	} );

	it( 'skips builds that did not finish, have no Pro zip, or lost it', () => {
		const lost = source( '20261013-120000-0007' );

		rmSync( path.join( lost.dir, 'wp-simple-pay-pro-4.17.5.zip' ) );

		const result = choices( [
			source( '20261013-120000-0004', { status: 'failed' } ),
			source( '20261013-120000-0005', { status: 'running' } ),
			source( '20261013-120000-0006', { artifacts: [ { name: 'stripe-4.17.5.zip', size: 10, kind: 'lite' } ] } ),
			lost,
		] );

		expect( result ).toEqual( [] );
	} );

	it( 'treats a build whose Lite zip is gone as Pro only', () => {
		const build = source( '20261013-120000-0008' );

		rmSync( path.join( build.dir, 'stripe-4.17.5.zip' ) );

		expect( choices( [ build ] )[ 0 ] ).toMatchObject( { lite: false, liteZip: null } );
	} );

	it( 'lists the newest build first', () => {
		const result = choices( [ source( '20261013-120000-0010' ), source( '20261013-120000-0030' ), source( '20261013-120000-0020' ) ] );

		expect( result.map( ( item ) => item.id ) ).toEqual( [ '20261013-120000-0030', '20261013-120000-0020', '20261013-120000-0010' ] );
	} );

	it( 'quotes a path outside the repo that has spaces', () => {
		const outside = mkdtempSync( path.join( tmpdir(), 'release console ' ) );

		try {
			const [ choice ] = choices( [ source( '20261013-120000-0009', {}, path.join( outside, 'build' ) ) ] );

			expect( choice.pro ).toBe( `'${ path.join( outside, 'build', 'wp-simple-pay-pro-4.17.5.zip' ) }'` );
		} finally {
			rmSync( outside, { recursive: true, force: true } );
		}
	} );

	it( 'offers nothing to a stage that cannot use a local build, or with no builds', () => {
		expect( choices( [ source( '20261013-120000-0011' ) ], findStage( 'analyze' )! ) ).toEqual( [] );
		expect( localBuildChoices( compare, { root, version: release, litePath: path.join( root, 'lite' ) } ) ).toEqual( [] );
		expect( states( release )[ 'compare-builds' ] ).toMatchObject( { localBuild: true, localBuilds: [] } );
		expect( states( release ).analyze ).toMatchObject( { localBuild: false, localBuilds: [] } );
	} );
} );
